CREATE TABLE t1(a,b); CREATE TABLE log(x UNIQUE, y); CREATE TRIGGER r1 AFTER INSERT ON t1 BEGIN UPDATE log SET y=y+1 WHERE x=new.a; INSERT OR IGNORE INTO log VALUES(new.a, 1); END; INSERT INTO t1 VALUES('hello','world'); INSERT INTO t1 VALUES(5,10); INSERT INTO t1 SELECT a, b+10 FROM t1; CREATE TABLE log2(x PRIMARY KEY,y); CREATE TRIGGER r2 BEFORE INSERT ON t1 BEGIN UPDATE log2 SET y=y+1 WHERE x=new.b; INSERT OR IGNORE INTO log2 VALUES(new.b,1); END; INSERT INTO t1 VALUES(453,'hi');